import{_ as s,C as i,o as t,c,a5 as a,b as n,w as o,a as l,E as d,a7 as p}from"./chunks/framework.QWVCgkrI.js";const A=JSON.parse('{"title":"Gitの保存モデル — blob・tree・commitとrefs／HEAD","description":"","frontmatter":{"title":"Gitの保存モデル — blob・tree・commitとrefs／HEAD","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"tools","summary":"2つのコミットを例に、Gitがファイル内容・名前・履歴・ブランチをどう結び付けるかを追い、差分表示とpack圧縮を区別する。","aliases":["Git objects","Gitオブジェクト","blob","tree","commit","refs","HEAD","packfile","Gitの内部構造"],"verification":"Git公式マニュアルとPro Gitに照合し、WindowsのGit 2.39.2で独立した2コミットのオブジェクトとpack化を実行確認（2026-11-17）"}},"headers":[],"relativePath":"tools/git-objects.md","filePath":"tools/git-objects.md"}'),h={name:"tools/git-objects.md"};function b(m,e,f,g,k,E){const r=i("Mermaid");return t(),c("div",null,[e[1]||(e[1]=a('<h1 id="gitの保存モデル-—-blob・tree・commitとrefs-head" tabindex="-1">Gitの保存モデル — blob・tree・commitとrefs／HEAD <a class="header-anchor" href="#gitの保存モデル-—-blob・tree・commitとrefs-head" aria-label="Permalink to &quot;Gitの保存モデル — blob・tree・commitとrefs／HEAD&quot;">​</a></h1><p><code>note.txt</code> の1行だけを変えてコミットし、<code>git diff &#39;HEAD^&#39; HEAD</code> で前後を比べると、<code>note.txt</code> の変更が表示されます。そのコミットを指定すれば、変更していない <code>keep.txt</code> も取り出せます。Gitが各コミットに結び付けるのは、追跡対象のファイルがその時点でどう並び、どんな内容だったかというスナップショットです。変更が少ないときは、複数のスナップショットで同じオブジェクトを参照できます。<a href="https://git-scm.com/book/en/v2/Git-Internals-Git-Objects" target="_blank" rel="noreferrer">Pro GitのGitオブジェクト解説</a></p><h2 id="この記事で分かること" tabindex="-1">この記事で分かること <a class="header-anchor" href="#この記事で分かること" aria-label="Permalink to &quot;この記事で分かること&quot;">​</a></h2><p>ファイルの内容・名前・履歴をGitが何に記録し、HEADからどうたどるか説明できます。コミットのスナップショットと、差分表示やpack（保存・転送の形式）を区別できます。</p><p><strong>どんなときに使うか</strong>　コミットから変更していないファイルも取り出せる理由や、コミットIDが何を指すかを知りたいときです。</p><h2 id="内容・名前・履歴はどこにあるか" tabindex="-1">内容・名前・履歴はどこにあるか <a class="header-anchor" href="#内容・名前・履歴はどこにあるか" aria-label="Permalink to &quot;内容・名前・履歴はどこにあるか&quot;">​</a></h2><table tabindex="0"><thead><tr><th>オブジェクト</th><th>何を持つか</th></tr></thead><tbody><tr><td>blob</td><td>ファイルとして保存したバイト列。ファイル名はtreeにあります。</td></tr><tr><td>tree</td><td>ディレクトリ内の各項目の名前、モード、オブジェクトID。通常のファイルはblob、サブディレクトリは別のtreeを参照します。</td></tr><tr><td>commit</td><td>ルートtreeのID、親コミットのID、作者・コミッターや日時、メッセージなど。最初のコミットに親はなく、マージコミットは複数の親を持てます。</td></tr></tbody></table><p>この分け方なら、ファイル名だけが変わり、Gitが保存するバイト列が同じ場合、treeは新しい名前の項目から同じblobを指せます。commitのルートtreeから名前と内容をたどり、commitの親から履歴をたどります。<a href="https://git-scm.com/book/en/v2/Git-Internals-Git-Objects" target="_blank" rel="noreferrer">Pro GitのGitオブジェクト解説</a></p><h2 id="_2コミットで変わるid、共有するid" tabindex="-1">2コミットで変わるID、共有するID <a class="header-anchor" href="#_2コミットで変わるid、共有するid" aria-label="Permalink to &quot;2コミットで変わるID、共有するID&quot;">​</a></h2><p>最初のコミットでは <code>keep.txt</code> に <code>keep</code>、<code>note.txt</code> に <code>old</code> を保存しました。次のコミットでは <code>note.txt</code> だけを <code>new</code> に変えました。図では矢印の先が参照先です。2つのtreeが <code>keep.txt</code> に同じblobを使っています。</p>',10)),(t(),n(p,null,{default:o(()=>[d(r,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20accTitle%3A%20Git%E3%81%AE2%E3%82%B3%E3%83%9F%E3%83%83%E3%83%88%E3%81%AE%E5%8F%82%E7%85%A7%E9%96%A2%E4%BF%82%0A%20%20%20%20accDescr%3A%20HEAD%E3%81%AFmain%E3%81%8B%E3%82%89%E3%82%B3%E3%83%9F%E3%83%83%E3%83%882%E3%82%92%E6%8C%87%E3%81%99%E3%80%82%E5%90%84%E3%82%B3%E3%83%9F%E3%83%83%E3%83%88%E3%81%8B%E3%82%89%E3%83%AB%E3%83%BC%E3%83%88tree%E3%80%81%E5%90%84tree%E3%81%8B%E3%82%89note.txt%E3%81%AE%E5%80%8B%E5%88%A5%E3%81%AEblob%E3%81%A8keep.txt%E3%81%AE%E5%85%B1%E9%80%9A%E3%81%AEblob%E3%82%92%E6%8C%87%E3%81%99%E3%80%82%0A%20%20%20%20h%5B%22HEAD%22%5D%20--%3E%20ref%5B%22refs%2Fheads%2Fmain%22%5D%20--%3E%20c2%5B%22commit%202%22%5D%0A%20%20%20%20c2%20--%3E%7Cparent%7C%20c1%5B%22commit%201%22%5D%0A%20%20%20%20c2%20--%3E%7Ctree%7C%20t2%5B%22tree%202%22%5D%0A%20%20%20%20c1%20--%3E%7Ctree%7C%20t1%5B%22tree%201%22%5D%0A%20%20%20%20t1%20--%3E%7Cnote.txt%7C%20old%5B%22blob%20old%22%5D%0A%20%20%20%20t1%20--%3E%20keep%5B%22blob%20keep%22%5D%0A%20%20%20%20t2%20--%3E%20keep%0A%20%20%20%20t2%20--%3E%7Cnote.txt%7C%20new%5B%22blob%20new%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<h3 id="コマンドで図の参照を確認する" tabindex="-1">コマンドで図の参照を確認する <a class="header-anchor" href="#コマンドで図の参照を確認する" aria-label="Permalink to &quot;コマンドで図の参照を確認する&quot;">​</a></h3><p>以下は独立した検証リポジトリの出力です。オブジェクトIDは先頭8桁に縮め、<code>cat-file -p</code> の作者情報などは省略しました。<code>HEAD^</code> はこの例では <code>HEAD</code> の第1親、<code>HEAD^{tree}</code> は今のコミットのルートtreeです。<a href="https://git-scm.com/docs/gitrevisions" target="_blank" rel="noreferrer">gitrevisions</a> · <a href="https://git-scm.com/docs/git-rev-parse" target="_blank" rel="noreferrer">git-rev-parse</a> · <a href="https://git-scm.com/docs/git-cat-file" target="_blank" rel="noreferrer">git-cat-file</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git rev-parse --show-object-format</span></span>
<span class="line"><span>sha1</span></span>
<span class="line"><span>$ git rev-parse HEAD &#39;HEAD^&#39; &#39;HEAD^{tree}&#39;</span></span>
<span class="line"><span>e5b25d89</span></span>
<span class="line"><span>07367563</span></span>
<span class="line"><span>8f993730</span></span>
<span class="line"><span>$ git cat-file -t HEAD</span></span>
<span class="line"><span>commit</span></span>
<span class="line"><span>$ git cat-file -p HEAD</span></span>
<span class="line"><span>tree 8f993730</span></span>
<span class="line"><span>parent 07367563</span></span>
<span class="line"><span>…</span></span></code></pre></div><p><code>ls-tree</code> は、各項目をモード・型・ID・名前の順に表示します。<code>keep.txt</code> は両方で <code>2fa992c0</code> を指し、<code>note.txt</code> のIDだけが変わっています。<code>cat-file -p</code> でそのblobを読むと、保存したバイト列が返ります。<a href="https://git-scm.com/docs/git-ls-tree" target="_blank" rel="noreferrer">git-ls-tree</a> · <a href="https://git-scm.com/docs/git-cat-file" target="_blank" rel="noreferrer">git-cat-file</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git ls-tree &#39;HEAD^&#39;</span></span>
<span class="line"><span>100644 blob 2fa992c0  keep.txt</span></span>
<span class="line"><span>100644 blob 3367afdb  note.txt</span></span>
<span class="line"><span>$ git ls-tree HEAD</span></span>
<span class="line"><span>100644 blob 2fa992c0  keep.txt</span></span>
<span class="line"><span>100644 blob 3e757656  note.txt</span></span>
<span class="line"><span>$ git cat-file -p &#39;HEAD:note.txt&#39;</span></span>
<span class="line"><span>new</span></span></code></pre></div><h2 id="headとブランチは履歴のどこを指すか" tabindex="-1">HEADとブランチは履歴のどこを指すか <a class="header-anchor" href="#headとブランチは履歴のどこを指すか" aria-label="Permalink to &quot;HEADとブランチは履歴のどこを指すか&quot;">​</a></h2><p>通常の状態では <code>HEAD</code> が現在のブランチ参照を指し、ブランチ参照がコミットを指します。例では <code>git symbolic-ref HEAD</code> が <code>refs/heads/main</code> を返します。<code>git rev-parse refs/heads/main</code> の結果は、図のコミット2を表す <code>e5b25d89…</code> です。</p><p><code>main</code> 上で新しいコミットを作ると <code>main</code> の参照先が進みます。コミット1は引き続きコミット2の親からたどれます。<a href="https://git-scm.com/book/en/v2/Git-Internals-Git-References" target="_blank" rel="noreferrer">Pro GitのGitの参照</a> · <a href="https://git-scm.com/docs/git-symbolic-ref" target="_blank" rel="noreferrer">git-symbolic-ref</a></p><h2 id="スナップショット、差分表示、packは何が違うか" tabindex="-1">スナップショット、差分表示、packは何が違うか <a class="header-anchor" href="#スナップショット、差分表示、packは何が違うか" aria-label="Permalink to &quot;スナップショット、差分表示、packは何が違うか&quot;">​</a></h2><p><code>git diff &#39;HEAD^&#39; HEAD</code> は、指定した2つのスナップショットから差分を作る表示です。この例では <code>note.txt</code> の <code>-old</code> と <code>+new</code> が出ます。commitには親のIDがあり、その時点の内容はルートtreeからたどれます。親との差分を順番につなげて、コミットの内容を求める構造とは異なります。<a href="https://git-scm.com/docs/git-diff" target="_blank" rel="noreferrer">git-diff</a> · <a href="https://git-scm.com/book/en/v2/Git-Internals-Git-Objects" target="_blank" rel="noreferrer">Pro GitのGitオブジェクト解説</a></p><p>一方、packはオブジェクトをまとめて保存・転送する形式です。オブジェクトを圧縮して収めるほか、似たオブジェクトを基底にして、そこから本体を復元するための<strong>デルタ</strong>を収める場合があります。基底の選び方は履歴の親子関係とは別で、画面に出る <code>git diff</code> のテキストとも別です。packから取り出した型と本体は、元の論理オブジェクトに戻ります。<a href="https://git-scm.com/docs/gitformat-pack" target="_blank" rel="noreferrer">Gitのpack形式仕様</a> · <a href="https://git-scm.com/book/en/v2/Git-Internals-Packfiles" target="_blank" rel="noreferrer">Pro GitのPackfiles</a></p><h2 id="補足" tabindex="-1">補足 <a class="header-anchor" href="#補足" aria-label="Permalink to &quot;補足&quot;">​</a></h2><h3 id="参照やidの保存形式" tabindex="-1">参照やIDの保存形式 <a class="header-anchor" href="#参照やidの保存形式" aria-label="Permalink to &quot;参照やIDの保存形式&quot;">​</a></h3><p>図は参照の論理的な関係です。<strong>detached HEAD</strong> は、<code>HEAD</code> がブランチ名を介さずにコミットを直接指す状態です。Gitの対応版では、<code>files</code> 形式は個別の参照ファイルや <code>packed-refs</code> を使い、<code>reftable</code> 形式は別の保存方式を使います。</p><p>オブジェクトIDはリポジトリの形式に依存します。今回の例はSHA-1です。対応するGitではSHA-256形式も選べます。IDを読むときは桁数を決め打ちせず、<code>git rev-parse --show-object-format</code> で形式を確認できます。<a href="https://git-scm.com/docs/git-init" target="_blank" rel="noreferrer">git-init</a> · <a href="https://git-scm.com/docs/git-rev-parse" target="_blank" rel="noreferrer">git-rev-parse</a></p><h3 id="_7オブジェクトをpack化した結果" tabindex="-1">7オブジェクトをpack化した結果 <a class="header-anchor" href="#_7オブジェクトをpack化した結果" aria-label="Permalink to &quot;7オブジェクトをpack化した結果&quot;">​</a></h3><p>検証用リポジトリをpack化すると、個別に保存されていた7オブジェクトが1つのpackに入りました。この小さな例では7個ともデルタを使わず、pack化する前後で、上のIDや <code>ls-tree</code>、blobの内容、<code>git diff</code> の出力は同じでした。packに入っていることと、デルタ表現で入っていることは区別できます。</p><h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2><ul><li>blobは内容、treeは名前と参照先、commitはルートtreeと親を持ちます。</li><li>ブランチ上ではHEADからブランチ参照と現在のコミットをたどれます。</li><li>内容が同じファイルは、別のtreeから同じblobを参照できます。</li><li><code>git diff</code> はスナップショットを比較し、packはオブジェクトを保存・転送するためにまとめます。</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><details class="details custom-block"><summary>同じバイト列のファイルを別名へ変えると、どこが変わる？</summary><p>ファイル名を持つtreeが変わり、その状態を記録する新しいcommitは新しいtreeを参照します。バイト列が変わっていないなら、同じblobを使えます。</p></details><details class="details custom-block"><summary>HEADから今の note.txt の内容まで、どの順にたどる？</summary><p>図の状態では、HEADから <code>refs/heads/main</code>、コミット2、ルートtree、<code>note.txt</code> の項目、<code>new</code> を持つblobの順です。</p></details><h2 id="検証範囲" tabindex="-1">検証範囲 <a class="header-anchor" href="#検証範囲" aria-label="Permalink to &quot;検証範囲&quot;">​</a></h2><p>2026年11月17日にWindowsのGit 2.39.2.windows.1で、SHA-1形式の独立したリポジトリに2コミットを作成して観察しました。<code>git cat-file</code>、<code>git ls-tree</code>、<code>git rev-parse</code>、<code>git symbolic-ref</code>、<code>git diff</code> とpack化の前後を照合しました。2026年11月20日には同じ版で別々のSHA-1とSHA-256の練習用リポジトリを作り、<code>--show-object-format</code> がそれぞれ <code>sha1</code>、<code>sha256</code> を返すことを確認しました。SHA-256でのpack化、reftable、デルタを使うpackの実測は対象外です。</p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li>次のコミットのtreeを作るために、indexが名前やblobのIDをどう保持するかを確かめる。<a href="/study/tools/git-staging-index.html">Gitのステージング — 作業ツリー・index・HEAD</a></li><li>マージコミットが指す二つの親と、統合の基準になる共通祖先を図でたどる。<a href="/study/tools/git-three-way-merge.html">Gitのマージ — 共通祖先と3-way merge</a></li><li>別の親の上に変更を適用し直すと、コミットIDがどう変わるかを確かめる。<a href="/study/tools/git-rebase.html">Gitのrebase — コミットの再適用と履歴の書き換え</a></li><li>同じ修正を別の親の上に記録し、元のコミットと新しいコミットのIDを比べる。<a href="/study/tools/git-cherry-pick.html">Gitのcherry-pick — コミットではなく変更を別の履歴へ取り込む</a></li><li>変更を打ち消したあとのtreeと、元のコミットを含む親のつながりを比べる。<a href="/study/tools/git-revert.html">Gitのrevert — 履歴を消さずに変更を打ち消す仕組み</a></li><li>ブランチが以前どのコミットを指していたか、ローカルの参照の移動記録からたどる。<a href="/study/tools/git-reflog.html">Gitのreflog — 履歴から見えなくなったコミットはどこにあるのか</a></li><li><code>refs/heads/main</code> と <code>refs/remotes/origin/main</code> が、ローカルにあるどの情報を表すかを確かめる。<a href="/study/tools/git-remote-tracking.html">Gitのリモート追跡ブランチ — origin/mainはサーバーそのものではない</a></li><li><a href="/study/tools/git-basics.html">Gitの基本</a> — 作業ツリー、ステージング、コミットの操作と差分の見方を確認する。</li><li><a href="/study/glossary/programming.html#branch">用語集のブランチ</a> — ブランチやマージなど、履歴を扱う用語を引く。</li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://git-scm.com/book/en/v2/Git-Internals-Git-Objects" target="_blank" rel="noreferrer">Pro Git — Git Objects</a></li><li><a href="https://git-scm.com/book/en/v2/Git-Internals-Git-References" target="_blank" rel="noreferrer">Pro Git — Git References</a></li><li><a href="https://git-scm.com/book/en/v2/Git-Internals-Packfiles" target="_blank" rel="noreferrer">Pro Git — Packfiles</a></li><li><a href="https://git-scm.com/docs/gitrevisions" target="_blank" rel="noreferrer">Git公式 — gitrevisions</a> · <a href="https://git-scm.com/docs/git-init" target="_blank" rel="noreferrer">git-init</a> · <a href="https://git-scm.com/docs/gitformat-pack" target="_blank" rel="noreferrer">gitformat-pack</a></li></ul>`,28))])}const D=s(h,[["render",b]]);export{A as __pageData,D as default};
